-- MainStoryGuide Journal text: Human storyline.
-- Original in-world retellings, written for this addon. Facts follow the
-- quest itself (cross-checked against Wowpedia / Warcraft Wiki quest
-- pages); no wiki text is reproduced. One entry per story quest, keyed
-- by quest ID. An entry only ever describes events up to and including
-- its own quest, so a locked page can never leak what comes later.
-- Epilogues are keyed by chain ID and unlock when the chain is DONE.

local _, ns = ...
ns.JournalEntries = ns.JournalEntries or {}
ns.JournalEpilogues = ns.JournalEpilogues or {}

local E = {
-- Chapter I: Northshire's Defence --------------------------------------
[783] = { title = "Orders at the Abbey",
  body = "Northshire Abbey stood under siege by neglect and vermin alike. Marshal McBride held the valley with a skeleton guard, watching the vineyard crawl with thieves while kobolds pressed from the surrounding hills. Stormwind sent neither banners nor reinforcements. The marshal had no need of parade-ground pomp; he needed steel and resolve to stem the tide." },
[7] = { title = "First Blood in the Vineyard",
  body = "The militia struck the fields north of the Abbey, cutting through the swarming kobolds that choked the harvest rows. Wretched and candle-obsessed, the creatures fought with frantic fury before scattering back toward the treeline. The vineyard workers reclaimed the soil under watchful eyes. It was a fragile respite, but the valley held." },
[15] = { title = "Echo Ridge",
  body = "A scout's report from the Echo Ridge shafts brought grim news to the Abbey. Kobold laborers choked the dark subterranean tunnels, clawing at the rock face as though the hills belonged to them alone. The creatures worked with an organized malice uncharacteristic of common vermin. Something drove them from the deeps with purposeful intent." },
[21] = { title = "The Skirmish",
  body = "The attack on Echo Ridge drove back the laborers and scattered their candlelit warrens. Steel clattered against pickaxes in the damp stone until the lower shafts fell quiet. Marshal McBride received confirmation of the purge, though silence in the hills rarely lasts. The ridge was secured, but the shadow behind the vermin lingered." },
[18] = { title = "Red Bandanas",
  body = "Bandits draped in red bandanas struck Northshire's vineyards, plundering the tenant farms with drilled precision. Calling themselves the Defias Brotherhood, these brigands moved with the coordinated discipline of a trained army rather than common outlaws. Proof of their defeat was delivered to Deputy Willem, raising an ominous question: who forged simple thieves into a disciplined legion?" },
[6] = { title = "Garrick Padfoot",
  body = "Garrick Padfoot, the cutthroat commanding the Defias raiders near the vineyard, met his end at the edge of his encampment. The outlaw died defiant, spitting contempt and boasting that the Brotherhood would outlive every soldier Stormwind could muster. His severed bounty brought relief to Northshire, yet his dying boast rang with chilling conviction." },
[54] = { title = "The Road South",
  body = "Marshal McBride dispatched urgent dispatches south across the river, directing the courier toward Marshal Dughan in Goldshire. The bells of Northshire Abbey echoed across the valley before fading into the forest canopy. The valley road ran clear toward the heart of Elwynn, but the kingdom's borders were already trembling." },
-- Chapter II: Shadows over Elwynn --------------------------------------
[3903] = { title = "Milly Osworth",
  body = "Beyond the Abbey walls, the Defias made a routine of pillaging Milly Osworth's vineyard. The farmers watched their hard-won harvest carted off under the threat of red-masked blades while the crown looked elsewhere. An appeal for aid reached the militia before the entire vintage fell into bandit hands. In Elwynn, every bushel defended was a battle for survival." },
[3904] = { title = "The Harvest",
  body = "The ripe grapes were recovered from the contested vines while Defias loiterers watched from the tree line, intimidated into silence. The Brotherhood did not seek crowns or high citadels in Northshire; they bled the realm by seizing the daily bread of common folk. Every crate rescued from the field denied sustenance to the growing rebellion." },
[3905] = { title = "A Manifest of Grapes",
  body = "Milly Osworth's signed harvest manifest reached Brother Neals at the Abbey, cataloguing every crate of the recovered vintage. Ledgers, tithes, and casks of wine: the mundane apparatus of the realm persisted despite the chaos encroaching upon its borders. That stubborn adherence to order remained the kingdom's fiercest shield against collapse." },
[62] = { title = "The Fargodeep Shafts",
  body = "Reconnaissance of the Fargodeep excavation south of Goldshire revealed a grim truth for Marshal Dughan. The royal ironworks, once buzzing with Stormwind laborers, lay completely abandoned to swarms of tunneling kobolds. No crown overseers remained, and no royal soldiers patrolled the perimeter. The realm's vital resources were slipping away in the dark." },
[76] = { title = "The Jasperlode Shafts",
  body = "The Jasperlode digs north of the road mirrored the disaster at Fargodeep. Kobolds held the subterranean galleries in force, while the King's pickaxes rusted where they fell. Marshal Dughan received the scouting report with the grim resignation of an officer whose repeated pleas for garrison reinforcements had met only silence from the capital." },
[35] = { title = "Further Concerns",
  body = "Marshal Dughan's worries stretched far beyond the crossroads of Goldshire. Word went east along the river road to Guard Thomas, who held the river bridge against the wild predators and encroaching murlocs of the forest borderlands. With only a handful of guards to defend the road toward the logging camp, the eastern frontier strained near the breaking point." },
[37] = { title = "The Lost Guards",
  body = "Two scouts of the Elwynn guard, Rolf and Malakai, vanished while tracking the murloc tribes gathering near Stone Cairn Lake. Guard Thomas remained trapped at the river crossing, unable to abandon his post and lacking soldiers to mount a search. The silence across the eastern waterways boded ill for the missing guards." },
[45] = { title = "What the Lake Kept",
  body = "The search ended on the muddy banks of Stone Cairn Lake, where the primitive huts of the murlocs displayed the savage fate of Rolf. The scout had fallen defending his position, leaving only his waterlogged medallion behind. Stormwind could spare neither reinforcements nor relief, and the forest wilds claimed another loyal defender." },
[71] = { title = "Bringing Back the News",
  body = "Word of Rolf's brutal end reached Guard Thomas at the river crossing. The veteran guard received the medallion in solemn silence, weighing the cost of duty against an undermanned frontier. There was no time for mourning along the eastern highway; the bridge still required vigilant defense against the creeping wild." },
[39] = { title = "Thomas' Report",
  body = "Guard Thomas penned a stark dispatch to Marshal Dughan detailing the loss of his scouts, the swelling murloc warrens, and the precarious state of the eastern bridge. The sealed report returned to Goldshire by courier. Yet ink and parchment were poor substitutes for battalions, and the pleas continued to accumulate upon distant desks in the capital." },
[52] = { title = "Protect the Frontier",
  body = "A swift cull along the eastern verge pushed back the forest prowlers and rabid bears stalking the logging trail. With the wild beasts driven from the tree line, timber wagons and couriers traversed the road toward the Eastvale Logging Camp unhindered. A trade road cleared of predators meant the kingdom had not yet surrendered the forest." },
[147] = { title = "Manhunt",
  body = "Marshal Dughan identified the shadowy figure orchestrating the plunder: the Collector, a vicious gnoll chieftain holed up beside the Brackwell Pumpkin Patch. A raid through the southwest woods ended the beast's reign, stripping the ornate gold ring from its corpse. The stolen ore shipments had financed a wider threat, but Elwynn's farmlands were avenged." },
[123] = { title = "The Collector's Schedule",
  body = "A crumpled parchment recovered from eastern Elwynn unmasked a coordinated operation: a detailed schedule timing shipments of refined gold to a recipient known as the Collector. With the royal ironworks overrun by vermin, illicit hands were extracting wealth from the kingdom's veins. Marshal Dughan studied the schedule with shock; someone was stripping Elwynn bare from within." },
[11] = { title = "Armbands of the Riverpaw",
  body = "The Riverpaw gnolls raiding the southwestern homesteads met swift steel near the border. Deputy Rainer at Westbrook Garrison collected painted leather armbands as proof of the beasts' demise. The gnoll warbands had sensed the kingdom's faltering grip on the frontier, but the garrison walls still held against the howling packs." },
[176] = { title = "Hogger",
  body = "The dread chieftain of the Riverpaw pack met justice in the deep forest. Hogger, a massive brute who had slaughtered merchants and militia along the southern border for years, finally fell in battle. The monster's severed claw was borne back to Goldshire as proof that the terror of the southwest was broken." },
[239] = { title = "Westbrook Garrison",
  body = "Orders from Goldshire pointed toward Westbrook Garrison, where the lush canopy of Elwynn broke against the arid bluffs of Westfall. The garrison guards kept a tense watch across the border, gazing westward as if awaiting an oncoming storm. Beyond the border gate lay a land long abandoned by the crown." },
}
for id, e in pairs(E) do ns.JournalEntries[id] = e end

E = {
-- Chapter III: The People's Militia ------------------------------------
[109] = { title = "Sentinel Hill",
  body = "Westfall offered only arid dust, abandoned barns, and the hollow silence of drought. At Sentinel Hill, Gryan Stoutmantle led the People's Militia, a band of displaced farmers and ploughmen wielding rusted blades. Royal soldiers had marched away to Stormwind years before, leaving the countryside to the Defias Brotherhood. Stoutmantle's ragged volunteers were all that stood between the people and oblivion." },
[12] = { title = "Ploughshares into Swords",
  body = "The militia struck the Defias trappers and smugglers occupying the homesteads around Sentinel Hill. These brigands had stripped the dying fields bare and harassed every farmer attempting to scratch a living from the soil. Driving them from the nearby pastures secured a foothold, proving that common laborers could hold their ground against seasoned outlaws." },
[13] = { title = "The War Widens",
  body = "Counterattacks pushed deeper into the dustlands, dislodging Defias looters and pillagers from the ruined outlying estates. Rotted windmills and fallow wheatfields bore witness to the prosperity Westfall had once known as the kingdom's breadbasket. Every reclaimed farm stood as a quiet indictment of a throne that had forgotten its people." },
[14] = { title = "Hard Men on the High Road",
  body = "A sweep of the high road broke the grip of Defias highwaymen and knuckledusters who blockaded the merchant paths. These men fought with martial discipline and unrelenting fury, marching like soldiers rather than disparate thieves. The Brotherhood had forged long-standing grievances into a lethal military machine, operating with deliberate strategic purpose." },
[102] = { title = "Patrolling Westfall",
  body = "Captain Danuvin directed the militia patrols against the Riverpaw gnolls wading across the southern border to plunder the remaining grain silos. The beasts were cut down along the river flats, easing the siege that gripped Westfall from both flanks. Surrounded by predators and bandits alike, the militia held fast with courage that shamed the distant court." },
-- Chapter IV: The Defias Brotherhood -----------------------------------
[65] = { title = "A Name Behind the Mask",
  body = "Gryan Stoutmantle abandoned any illusion that the Defias were simple bandits. The Brotherhood possessed leadership, coin, and a grand design, directed by an unseen hand behind the red masks. The militia commander called in an old debt, seeking intelligence from within the Brotherhood's shadow to unmask the mastermind orchestrating Westfall's ruin." },
[132] = { title = "Wiley's Note",
  body = "In Lakeshire, Wiley the Black delivered a sealed missive destined for Gryan Stoutmantle at Sentinel Hill. The veteran contact had pierced the secrecy shielding the Defias leadership, confirming that the conspiracy stretched far beyond the borders of Westfall. The dispatch traveled west across the kingdom, carrying intelligence that would shatter the militia's doubts." },
[135] = { title = "Wiley's Note, Onward",
  body = "Gryan Stoutmantle forwarded Wiley's encrypted intelligence directly to Stormwind, addressed to Master Mathias Shaw of SI:7. Each officer who handled the parchment recognized the peril within its lines, forwarding the warning through covert channels. A conspiracy protected with such desperate caution reached toward the highest seats of power." },
[141] = { title = "The Spymaster's Report",
  body = "Master Mathias Shaw analyzed Wiley's findings in the clandestine headquarters of Old Town, compiling a confidential dossier for Sentinel Hill. The spymaster confirmed that the red bandanas were merely the outward banner of an organized rebellion directed by former guild artisans. The conflict had escalated from peasant skirmishes into a shadow war for the realm." },
[142] = { title = "What Shaw Knows",
  body = "Shaw's dossier unmasked the bitter history behind the uprising. The Stonemasons' Guild had reconstructed Stormwind stone by stone, only for the House of Nobles to withhold their rightful payment and banish them in disgrace. At the head of the bitter artisans stood Edwin VanCleef, the guild master turned rebel architect. A Defias courier was tracked across Westfall to secure indisputable proof." },
[155] = { title = "Proof, of a Sort",
  body = "The investigation converged upon a captured Defias traitor who bargained his survival for the location of the Brotherhood's secret redoubt. Escorted under guard through the dusty trails of Westfall, the turncoat pointed toward the entrance of the Moonbrook hideout where VanCleef commanded his forces. The faceless rebellion was finally cornered in its subterranean lair." },
[166] = { title = "The Deadmines",
  body = "The militia stormed the subterranean cavern beneath Moonbrook, where the Defias had assembled a colossal ironclad warship destined for Stormwind Harbor. Fighting through the rebel lieutenants, the assault culminated on the warship's deck, where Edwin VanCleef fell in combat. The architect of the rebellion was slain, ending his bloody bid to drown the capital in fire." },
[373] = { title = "An Unsent Letter",
  body = "An unsent letter recovered from VanCleef's quarters was addressed to Baros Alexston, Stormwind's chief city architect. The missive proved that the lines of treason reached directly into the capital's municipal administration. Although the Brotherhood's warlord lay dead, the underlying conspiracy remained rooted within the gilded halls of the city itself." },
-- Chapter V: Redridge Under Siege --------------------------------------
[244] = { title = "Word from the East",
  body = "Reports of war reached Goldshire from the eastern crags, where gnoll howls and battle horns echoed down from Redridge. In Lakeshire, the mountain township faced total encirclement by savage tribes and darker forces gathering in the heights. Once again, a border settlement called upon Stormwind for salvation, only to be met with deafening silence." },
[20] = { title = "The Blackrock Menace",
  body = "Marshal Marris mounted a desperate stand against the Blackrock orcs spilling into the Redridge valleys from the Burning Steppes. Veteran legions of the old Horde marched through the northern canyons with deliberate military force, probing for vulnerabilities along the frontier. Lakeshire held the pass with town guards and volunteers, guarding the gateway to the kingdom." },
[34] = { title = "An Unwelcome Guest",
  body = "A monstrous hill boar known as Bellygrub terrorized the homesteads above Lakeshire, rooting through the remaining crops and destroying vital food stores. A decisive hunt brought down the rampaging beast, delivering its massive tusk to Guard Parker. Even under the shadow of invasion, safeguarding the harvest gave the besieged town strength to endure." },
[125] = { title = "The Lost Tools",
  body = "Foreman Oslow of Lakeshire had lost his toolbox to the bottom of Lake Everstill. The toolbox was raised from the lake bed and carried back to him in Lakeshire. With his tools in hand again, Oslow could turn to the Everstill Bridge." },
[89] = { title = "The Everstill Bridge",
  body = "Foreman Oslow struggled to complete the grand stone bridge across Lake Everstill despite constant raids by gnolls and lake creatures. Stolen iron tools and building materials were wrested back from the thieves, allowing construction to resume. Span by span, Lakeshire built for the future under fire, holding faith while the royal court debated in safety." },
[91] = { title = "Solomon's Law",
  body = "Magistrate Solomon governed Redridge with an unyielding devotion to the law and an empty garrison roster. Armed resistance against the orc vanguard enforced the magistrate's decrees, breaking the enemy patrols massing along the ridges. Solomon accepted the victory with somber gratitude, well aware that parchment decrees meant nothing without blades to enforce them." },
-- Chapter VI: The Stockade Uprising ------------------------------------
[377] = { title = "Crime and Punishment",
  body = "The death of VanCleef did not extinguish the Defias conspiracy. In Duskwood, Councilman Millstipe demanded justice against Dextren Ward, an infamous Defias prisoner incarcerated within the Stormwind Stockade. Behind the prison bars, the Brotherhood continued to organize and plot, turning iron cells into an armed staging ground for insurrection." },
[386] = { title = "What Comes Around",
  body = "In Lakeshire, Guard Berton remembered Targorr the Dread, a Blackrock warlord captured during the mountain raids and held within Stormwind's dungeons. Word from the capital revealed that the captive orc was inciting rebellion from within his cell. A reckoning was demanded to settle the blood debt owed to the people of Redridge." },
[387] = { title = "Quell the Uprising",
  body = "Warden Thelwater struggled to hold the outer gates of the Stockade as prisoners revolted in a violent bid for freedom. Defias convicts and armed insurgents seized the cellblocks, transforming the royal dungeon into a fortress of the condemned. An armed descent into the damp corridors crushed the rioters before the insurrection spilled into the streets." },
[388] = { title = "The Color of Blood",
  body = "Investigation of the colored bandanas recovered from the rioting convicts revealed an elaborate heraldry of rebellion. Nikova Raskol deciphered the insignias, proving that the Brotherhood maintained distinct ranks and chains of command even behind iron bars. The Defias network had been designed to endure decapitation, functioning as a shadow state rather than a common band." },
[389] = { title = "Bazil Thredd",
  body = "Confronted with VanCleef's unsent letter, Baros Alexston directed the investigation toward Warden Thelwater with an urgent warning: Bazil Thredd, the surviving head of the Defias conspiracy, was orchestrating the prison uprising from his cell. The threads of municipal corruption and armed rebellion intersected within the stone bowels of the city dungeon." },
[391] = { title = "The Stockade Riots",
  body = "The suppression of the Stockade culminated in the execution of Bazil Thredd within the central cellblock. Defias insurgents, Blackrock brutes, and Dark Iron infiltrators were cut down in the corridors, breaking the back of the coordinated prison riot. The heavy iron portcullis slammed shut once more, leaving the capital quiet above a smoldering cellar." },
}
for id, e in pairs(E) do ns.JournalEntries[id] = e end

E = {
-- Chapter VII: The Legend of Stalvan -----------------------------------
[66] = { title = "A Faded Journal Page",
  body = "Within the ruined schoolhouse of Moonbrook, an abandoned footlocker yielded a tattered journal page yellowed by decades of dust. The elegant penmanship belonged to a private tutor, hired to educate the children of a noble house. Yet beneath the refined prose ran a dark, possessive pride signed by Stalvan Mistmantle. A forgotten tragedy began to stir in the silence." },
[67] = { title = "Asking After Ghosts",
  body = "Gryan Stoutmantle studied the recovered script, his hardened soldier's demeanor turning somber at the name of Mistmantle. The militia captain recalled the name as a whispered ghost story from a darker era, advising that any official documentation would rest in the archives of Darkshire. The long-dead tutor cast a lingering chill across the sunlit fields." },
[68] = { title = "The Old Footlocker",
  body = "Additional documents recovered from the schoolhouse footlocker survived the devastation that claimed Moonbrook. Sealed letters and fragmented notes pointed eastward into the gloomy forest of Duskwood. The forgotten papers carried the weight of an unresolved atrocity, demanding that the truth be brought into the light." },
[69] = { title = "Clerk Daltry's Records",
  body = "In the town hall of Darkshire, Clerk Daltry guarded municipal archives that preserved the dark history of the province. Searching through faded ledgers uncovered the record of Stalvan Mistmantle: a steady progression of appointments, sudden dismissals, and hushed scandals that society had conspired to bury. The ink remembered what living men wished to forget." },
[70] = { title = "Ripped Pages",
  body = "A closer inspection of Darkshire's town registry revealed jagged edges where entire pages had been deliberately excised. Someone of standing had sanitized the record, attempting to erase the tutor's escalating madness. The surviving notes traced Stalvan from one prominent estate to the next, fleeing dismissals shrouded in scandalous whispers." },
[72] = { title = "The Tutor",
  body = "The pieced-together correspondence revealed the portrait of a brilliant, arrogant scholar hired to instruct the youth of the Forlorn estate. When Stalvan's fixation fell upon the young daughter of the house, his courtly manners gave way to monstrous delusion. Cast out in disgrace, the rejected tutor nurtured a psychotic hatred behind the guise of wounded honor." },
[74] = { title = "Mistmantle's Brother",
  body = "In the taverns of Stormwind, Tobias Mistmantle lived under the shadow of the infamous family name. Confronted with the inquiry, Tobias surrendered personal letters written during his brother's descent into madness. The intimate missives chronicled the unraveling of Stalvan's sanity, preserved by a brother who had watched the tragedy unfold from afar." },
[75] = { title = "What the Letters Say",
  body = "The final letters stripped away every pretense of civility, charting devotion curdling into psychotic obsession. When the young noblewoman announced her betrothal to another, Stalvan's script turned venomous and precise. The concluding missive contained no pleas for reconciliation, only the chilling finality of a planned massacre." },
[78] = { title = "The Grandma's Tale",
  body = "An elder of Darkshire recounted the horror the ledgers dared not record: the night the rejected tutor returned to the estate with an axe. The entire noble household was butchered in their beds, their screams swallowed by the fog-shrouded night. What youth dismissed as a fireside ghost story had been a massacre carved into flesh and bone." },
[79] = { title = "The Night Watch Listens",
  body = "Commander Althea Ebonlocke of the Night Watch received the assembled evidence with grim certainty. Manor Mistmantle had loomed derelict upon its hill for decades, a cursed blight that the Watch could no longer tolerate. Althea sanctioned an armed expedition to put down the spectral butcher, warning that the estate harbored horrors that despised the living." },
[80] = { title = "Completing the Record",
  body = "The gathered testimonies, bloodstained letters, and registry notes returned to Clerk Daltry to complete the official record. In Duskwood, even atrocities and restless spirits required precise documentation before the Night Watch delivered judgment. Daltry entered the final testimony into the archives with trembling hands." },
[97] = { title = "Daltry's Findings",
  body = "Clerk Daltry compiled the verified ledger entries, personal letters, and sworn testimonies into a formal dossier for the Night Watch. In a haunted forest where horrors walk in the dark, official records preserved the moral clarity of the living. The truth stood vindicated on parchment; only the execution of justice remained." },
[98] = { title = "Manor Mistmantle",
  body = "The reckoning arrived at the rotting hall of Manor Mistmantle. Bound to the site of his slaughter, the ghost of Stalvan raged against the living with bitter hatred. Steel and righteous fury shattered the undead fiend, recovering the heirloom ring of the butchered family for Madame Eva. The murderer was laid to rest in the ashes of his crime, reducing a living nightmare back to a cautionary tale." },
-- Chapter VIII: The Darkness of Duskwood --------------------------------
[56] = { title = "Joining the Night Watch",
  body = "In Darkshire, the defense of the realm fell upon the Night Watch, a stalwart militia of local citizens holding the perimeter against endless nightmare. Stormwind's garrison had long departed, leaving townspeople to shoulder crossbows and patrol the mist-laden roads. Here, as across the kingdom's forgotten provinces, survival depended solely on those who refused to abandon their homes." },
[57] = { title = "The Watch's Work",
  body = "Night Watch patrols executed grim sweeps along the borders of Raven Hill, cutting down the skeletal ghouls and skeletalfiends that emerged from the fog. In Duskwood, the soil offered no peace to the deceased, demanding constant vigilance and ready steel. Every monstrosity felled in the forest edge protected the fragile sanctuary of Darkshire." },
[58] = { title = "Plague Spreaders",
  body = "A brutal purge struck the necrotic horrors that gathered near the Raven Hill mausoleums. Commander Ebonlocke ordered the eradication of the plague spreaders before their contagion could seep into the town's wells. The defense of Duskwood required unrelenting resolve, grinding down the undead hordes wave by wave amidst the moldering crypts." },
[95] = { title = "Sven's Revenge",
  body = "Sven Yorgen lived in seclusion in far western Duskwood, an embittered veteran driven solely by the thirst for vengeance. His farmstead had been torched and his family butchered by unknown terrors. The shattered soldier swore an unyielding oath to track the culprits to the ends of the earth, demanding blood for blood." },
[230] = { title = "Sven's Camp",
  body = "A battered footlocker at Sven's abandoned campsite along the southern ridge yielded personal effects and weathered journal pages. The secluded camp had served as the soldier's temporary refuge after the massacre of his loved ones. The retrieved documents confirmed that sinister forces had stalked the farmstead long before the final slaughter." },
[262] = { title = "The Shadowy Figure",
  body = "Sven's recovered journal chronicled sightings of a cloaked stranger lurking around the farmstead days prior to the tragedy. The mysterious figure had interrogated locals in Darkshire concerning ancient burial mounds and forgotten relics. The massacre had not been random savagery; it was tied to a sinister hunt for forbidden power." },
[265] = { title = "The Shadowy Search Continues",
  body = "Madame Eva gazed into her scrying mist in Darkshire, sensing the dark aura of the cloaked intruder. The seer confirmed that the stranger had visited the town seeking ancient lore, directing the inquiry toward municipal records to trace the visitor's movements. Every step through the shadowed forest brought the truth closer to the light." },
[266] = { title = "Inquire at the Inn",
  body = "Town registries pointed toward the Scarlet Raven Inn, where travelers and merchants congregated beneath the dim lanterns. Clerk Daltry confirmed that the suspicious stranger had lodged at the tavern while conducting inquiries about the surrounding woods. Behind the taproom chatter lay the eyewitness accounts that would break the mystery open." },
[453] = { title = "Finding the Shadowy Figure",
  body = "Tavernkeep Smitts recalled the cloaked stranger's peculiar questions regarding the abandoned diggings at Roland's Doom. The visitor had paid in strange coin and slipped away into the night, heading toward the western ridges. What had begun as hushed tavern rumors solidified into a direct trail toward the source of the curse." },
[268] = { title = "Return to Sven",
  body = "The trembling hermit Jitters confessed the horrifying reality behind the stranger's quest: excavators digging for the Scythe of Elune at Roland's Doom had unleashed the feral worgen upon Duskwood. Word returned to Sven Yorgen with the full account of the catastrophe. The family had fallen as collateral damage in a mad hunt for an ancient relic." },
[323] = { title = "Sven's Test",
  body = "Sven Yorgen asked for proof of worth. Skeletal Raiders, Skeletal Healers and Skeletal Warders fell, and the proof went back to Sven at his camp." },
[269] = { title = "Seeking Wisdom",
  body = "Jitters' completed journal left Duskwood. Sven sent it to Stormwind, and it came into the hands of Bishop Farthing." },
[270] = { title = "The Doomed Fleet",
  body = "Bishop Farthing sent the matter on to Menethil Harbor in the Wetlands, where Glorin Steelbrow waited." },
[321] = { title = "Lightforge Iron",
  body = "Glorin Steelbrow pointed to the wreckage of The Flying Osprey. In the wreck lay a Waterlogged Chest." },
[324] = { title = "The Lost Ingots",
  body = "The Waterlogged Chest led to the Lightforge Ingots. Five of them were gathered and carried back to Glorin Steelbrow." },
[322] = { title = "Blessed Arm",
  body = "The Crate of Lightforge Ingots went from Glorin Steelbrow in Menethil Harbor to Grimand Elmore in Stormwind." },
[325] = { title = "Armed and Ready",
  body = "Grimand Elmore handed over Morbent's Bane. The weapon went back to Sven Yorgen's camp in Duskwood." },
[55] = { title = "Morbent's Bane",
  body = "High above the desolate tombstones of Raven Hill, the necromancer Morbent Fel raised legions of the restless dead from their graves. An enchanted weapon, Morbent's Bane, pierced the warlock's unholy wards and brought him down in his haunted manse. The necromantic rituals collapsed into dust, sparing Darkshire from an army of the risen." },
-- Chapter IX: The Missing Diplomat --------------------------------------
[1274] = { title = "The Search Begins",
  body = "Thomas in Stormwind City gave the task to find Bishop DeLavey in Stormwind Keep. Bishop DeLavey was found there." },
[1241] = { title = "Bishop DeLavey",
  body = "Bishop DeLavey in Stormwind City gave the task to find Jorgen. Jorgen was found in Stormwind City." },
[1242] = { title = "Jorgen's Sealed Note",
  body = "Jorgen in Stormwind City gave the task to deliver a sealed note. Jorgen's Sealed Note was delivered to Elling Trias in Stormwind City." },
[1243] = { title = "A Note for Duskwood",
  body = "Elling Trias in Stormwind City gave the task to take the Sealed Note to Duskwood. The note was delivered to Watcher Backus in Duskwood." },
[1244] = { title = "The Defias Docket",
  body = "Watcher Backus in Duskwood gave the task to find the Defias Docket. The Defias Docket was found and returned to Watcher Backus in Duskwood." },
[1245] = { title = "The Docket Returns",
  body = "Watcher Backus in Duskwood gave the task to bring the Defias Docket to Stormwind City. The docket was delivered to Elling Trias in Stormwind City." },
[1246] = { title = "Word with Stonefist",
  body = "Elling Trias in Stormwind City gave the task to speak to Dashel Stonefist. Dashel Stonefist was found and spoken to in Stormwind City." },
[1447] = { title = "Stonefist Defeated",
  body = "Dashel Stonefist in Stormwind City gave the task to defeat him. Dashel Stonefist was defeated in Stormwind City." },
[1247] = { title = "Back to Trias",
  body = "Dashel Stonefist in Stormwind City gave the task to speak to Elling Trias. Elling Trias was spoken to in Stormwind City." },
[1248] = { title = "To Menethil Harbor",
  body = "Elling Trias in Stormwind City gave the task to speak to Mikhail in the Wetlands. The report went to Mikhail at the inn in Menethil Harbor." },
[1249] = { title = "Slim Bolts",
  body = "Mikhail in the Wetlands gave the task to subdue Tapoke Jahn before he escaped. Tapoke Jahn was subdued, and the report went back to Mikhail in Menethil Harbor." },
[1250] = { title = "What Slim Knew",
  body = "Tapoke \"Slim\" Jahn in the Wetlands gave the task to speak to Mikhail. What Tapoke Jahn revealed was carried back to Mikhail in the Wetlands." },
[1264] = { title = "Word for Dustwallow Marsh",
  body = "Mikhail in the Wetlands gave the task to find Commander Samaul in Dustwallow Marsh. Commander Samaul was found in Dustwallow Marsh." },
[1265] = { title = "Sentry Point",
  body = "Commander Samaul in Dustwallow Marsh gave the task to search Sentry Point for any sign of Private Hendel. The report was delivered to Archmage Tervosh in Dustwallow Marsh." },
[1266] = { title = "The Search for Hendel",
  body = "Archmage Tervosh in Dustwallow Marsh gave the task to find Private Hendel. Private Hendel was found in Dustwallow Marsh." },
[1324] = { title = "Private Hendel Defeated",
  body = "Private Hendel was defeated in Dustwallow Marsh, and the result went back to Archmage Tervosh." },
[1267] = { title = "Lady Jaina Proudmoore",
  body = "Archmage Tervosh in Dustwallow Marsh gave the task to speak to Lady Jaina Proudmoore. The whole trail was presented to Lady Jaina Proudmoore in Dustwallow Marsh." },
}
for id, e in pairs(E) do ns.JournalEntries[id] = e end

E = {
-- Chapter X: Onyxia - The True Masters ----------------------------------
[4182] = { title = "Dragonkin Menace",
  body = "Black dragonkin stalked the volcanic ash of the Burning Steppes, their disciplined patrols answering to the brood of Blackrock Mountain. Helendis Riverhorn directed strikes against the scaled invaders, yet the presence of dragon armies on Stormwind's northern border raised grave concerns. A monstrous hand directed these forces, while the capital stubbornly ignored the encroaching flame." },
[4183] = { title = "The True Masters, Part One",
  body = "At Morgan's Vigil, Marshal Maxwell arrived at a terrifying certainty: an unseen power ruled the capital, systematically sabotaging the realm's defenses. Maxwell penned an urgent dispatch to Magistrate Solomon in Redridge, demanding to know who held the authority to deny aid to every frontier outpost. The investigation had moved from hunting monsters to identifying the traitors at the throne." },
[4184] = { title = "Solomon's Seal",
  body = "Magistrate Solomon endorsed Maxwell's allegations with the official seal of Redridge, lending civic authority to an indictment of high treason. The joint petition bypassed intermediate bureaucrats, destined for Highlord Bolvar Fordragon in Stormwind Keep. Two veteran servants of the realm had pledged their lives to break the silence that paralyzed the court." },
[4185] = { title = "Before the Highlord",
  body = "The accusations were placed directly before Highlord Bolvar Fordragon in the throneroom of Stormwind Keep. At the regent's elbow stood Lady Katrana Prestor, calm and composed, subtly deflecting every concern with polished disdain. An unnatural chill permeated the court; the regent was blind to the manipulation unfolding beside the empty throne." },
[4186] = { title = "The Court Decides",
  body = "The royal court responded with smooth evasions, burying Maxwell's warning beneath demands for further inquiries and bureaucratic reviews. Lady Prestor's influence guided the council into deliberate paralysis, mirroring the abandonment suffered by Westfall and Redridge. The conspiracy was not a consequence of bureaucratic neglect; it was a weapon wielded by someone whispering directly into the regent's ear." },
[4223] = { title = "Back Along the Chain",
  body = "Magistrate Solomon received Stormwind's hollow reply with weary grief, recognizing that polite dismissals concealed betrayal at the highest levels. Yet scouts in the Burning Steppes had uncovered a vital lead: an eccentric hermit known as Ragged John possessed critical knowledge of the court's darkest secrets. The quest for truth abandoned legal petitions in favor of direct action." },
[4224] = { title = "Ragged John",
  body = "Over a campfire in the volcanic ash, Ragged John revealed the tragic fate of Marshal Reginald Windsor. Windsor had uncovered the identity of the power controlling the court, only to be branded a madman and left to rot in the dungeons of Blackrock Depths by Dark Iron captors. The key to saving the kingdom lay locked in chains beneath the mountain." },
[4241] = { title = "Marshal Windsor",
  body = "Marshal Maxwell issued the call to breach Blackrock Mountain and locate Reginald Windsor. The disgraced hero was the only man alive who possessed the proof required to unmask the court's puppet masters. A dangerous descent into the fiery underworld began, aimed at extracting the kingdom's forgotten marshal from his subterranean tomb." },
[4242] = { title = "Abandoned Hope",
  body = "Deep in the Detention Block of Blackrock Depths, Reginald Windsor sat in darkness, gaunt and disillusioned. The imprisoned marshal initially refused rescue, convinced that returning without his stolen evidence would achieve nothing against the creature masquerading in the keep. Without his documented proofs, freedom was merely an illusion." },
[4264] = { title = "A Crumpled Up Note",
  body = "A crumpled parchment taken from a slain Dark Iron jailer revealed the location of Windsor's confiscated intelligence. The commander of the Depths and the golem lord had divided the classified documents between them as trophies. When shown the note, the broken marshal felt the rekindling of hope, realizing that his life's work was still recoverable." },
[4282] = { title = "A Shred of Hope",
  body = "Raids into the subterranean workshops eliminated General Angerforge and Golem Lord Argelmach, wresting Windsor's missing manifests from their grasp. Armed with his decrypted evidence, the veteran marshal stood tall once more, prepared to challenge the corruption gripping the realm. The time had come to escort the fallen hero from the depths of the mountain." },
[4322] = { title = "Jail Break",
  body = "A fierce battle raged through the cellblocks as the prison doors swung wide. Reginald Windsor fought with legendary ferocity, cutting through waves of Dark Iron guards and golems to reach the subterranean exit. Emerging into the scorched air of the Burning Steppes, the marshal turned his gaze westward toward the capital to deliver judgment." },
[6402] = { title = "Stormwind Rendezvous",
  body = "Reginald Windsor arrived at the Valley of Heroes before the towering gates of Stormwind. Flanked by loyal soldiers, the marshal marched openly down the cobblestone avenues, his clanking armor heralding the arrival of truth. The masquerade was over; the exiled officer entered Stormwind Keep to confront the royal court in broad daylight." },
[6403] = { title = "The Great Masquerade",
  body = "Before the assembled court in Stormwind Keep, Reginald Windsor confronted Lady Katrana Prestor and read the ancient draconic words that shattered her mortal illusion. The court advisor stood revealed as Onyxia, broodmother of the black dragonflight. The dragon had manipulated the nobles, starved the provinces, and stoked the Defias rebellion to dismantle the kingdom from within. Windsor fell heroically to the beast's fury before Bolvar Fordragon drove the monster from the throneroom. The cost was devastating, but the kingdom's eyes were opened at last." },
[6501] = { title = "The Dragon's Eye",
  body = "Highlord Bolvar Fordragon took command of the shattered court, determined to hunt down the fled dragon. Piercing the wards guarding Onyxia's lair in Dustwallow Marsh required ancient draconic magic. An emissary was dispatched to the frozen heights of Winterspring to seek Haleh, a wyrm of the blue dragonflight capable of forging an amulet to breach the broodmother's sanctuary." },
[6502] = { title = "Drakefire Amulet",
  body = "In the caverns of Mazthoril, Haleh revealed the ritual to key the Drakefire Amulet: the blood of General Drakkisath, high commander of Blackrock Spire. Champions scaled the spire and slew the dragonkin warlord in his throne room. Imbued with draconic essence, the forged amulet unlocked the sealed gateway of Onyxia's Lair. The long road of neglected provinces, missing kings, and courtly treason led into the subterranean dark of Dustwallow for the final confrontation." },
}
for id, e in pairs(E) do ns.JournalEntries[id] = e end

local P = {
northshire = { title = "Epilogue: Northshire's Defence",
  body = "Northshire Abbey stood firm. The subterranean shafts were cleared of vermin, the vineyards secured, and dispatches dispatched south to Goldshire. Yet the dying boast of Garrick Padfoot echoed across the valley: the Defias Brotherhood would endure. The skirmishes at the Abbey fence line were merely the first stirrings of a disciplined rebellion threatening to tear the kingdom apart." },
elwynn = { title = "Epilogue: Shadows over Elwynn",
  body = "Elwynn Forest achieved a hard-won peace. Hogger fell in the deep woods, the river crossings stood guarded, and the lost scouts of Stone Cairn Lake were avenged. Beneath the surface, however, the realm bled: iron excavations lay abandoned, illicit gold flowed into the hands of shadowy conspirators, and dispatches to the capital met only silence. The true shadow over Elwynn was cast not by wild beasts, but by the vacant throne of Stormwind." },
peoples_militia = { title = "Epilogue: The People's Militia",
  body = "Westfall survived because its agrarian folk took up rusted steel and became an army. Every grain silo defended stood as a silent rebuke to a crown that had withdrawn its battalions and turned a blind eye. The People's Militia held the frontier because the royal army never arrived. A province forced to bleed for its own salvation would never view the throne in the same light again." },
defias_brotherhood = { title = "Epilogue: The Defias Brotherhood",
  body = "Edwin VanCleef was dead, his colossal ironclad warship thwarted, and the leadership of the Defias Brotherhood severed. Westfall could finally draw breath. Yet the root of the rebellion remained unhealed: the Stonemasons had rebuilt Stormwind, only to be betrayed by corrupt nobility. The unsent letters found in the Deadmines proved that while the warlord of the slums had fallen, the conspirators in the capital still held court in silk and velvet." },
redridge = { title = "Epilogue: Redridge Under Siege",
  body = "Lakeshire endured against overwhelming odds. The great stone bridge arched across Lake Everstill, Warlord Gath'Ilzogg lay dead, and the ramparts of Stonewatch Keep fell dark. Redridge held the mountain pass with raw courage and empty muster rolls. Across three provinces, the pattern was undeniable: Stormwind's neglect was no accident of distance, but a deliberate failure orchestrated at the highest level of government." },
stockade = { title = "Epilogue: The Stockade Uprising",
  body = "The Stormwind Stockade fell silent once more. Bazil Thredd and the rebel chiefs were executed in the dark, restoring Warden Thelwater's control over the heavy iron gates. Yet the riot revealed a terrifying truth: Defias insurgents, Blackrock orcs, and Dark Iron dwarves had coordinated their rebellion beneath the city streets. Locking enemies in dark cells had merely allowed diverse evils to conspire in secret." },
stalvan = { title = "Epilogue: The Legend of Stalvan",
  body = "Stalvan Mistmantle was finally laid to rest, his cursed manor silenced and his victims avenged decades after the slaughter. The horror of his legacy lay in the polite society that had protected him: noble families who whispered excuses and clerks who excised records to avoid scandal. Duskwood bred restless spirits because the living buried truth shallowly. Stalvan was no tragic legend; he was a murderer nurtured by complicity." },
duskwood_darkness = { title = "Epilogue: The Darkness of Duskwood",
  body = "The necromancer Morbent Fel was destroyed, the Night Watch held the fog-shrouded roads, and the slaughter of Sven Yorgen's family was traced to its horrific source. Seekers digging for the Scythe of Elune at Roland's Doom had unleashed the feral worgen upon the land. The nightmare choking Duskwood was born of mortal greed, neglected frontiers, and ancient artifacts unsealed. The dead walked because the living refused to reckon with their sins." },
missing_diplomat = { title = "Epilogue: The Missing Diplomat",
  body = "The investigation into the missing sovereign converged upon Theramore Isle, establishing the conspiracy while King Varian Wrynn remained captive. Every disaster afflicting the realm—the starving militias, the Defias war fleets, the abandoned garrisons—stemmed directly from the vacant throne of Stormwind. Conspirators had deliberately stolen the monarch away to paralyze the Alliance. The trail paused at the edge of the western sea, but the struggle to restore the King had only just begun." },
onyxia = { title = "Epilogue: The True Masters",
  body = "A black dragon had seized the realm from within. Disguised as Lady Katrana Prestor, Onyxia had manipulated the regent, starved the outer provinces, and stoked the fires of rebellion from the King's own throneroom. Marshal Reginald Windsor gave his life to rip away the broodmother's masquerade. Keyed with dragon blood, the Drakefire Amulet opened the road to her volcanic lair in Dustwallow Marsh. The truth was unmasked not by royal decrees, but by embattled marshals, ragged militias, and relentless defenders who refused to let the kingdom perish in the dark." },
}
for id, e in pairs(P) do ns.JournalEpilogues[id] = e end
